-- Edu-Adapt schema (matches the existing XAMPP `eduadapt` database).
CREATE DATABASE IF NOT EXISTS eduadapt CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE eduadapt;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS subjects (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, subject_name VARCHAR(100) NOT NULL, credits INT DEFAULT 0, priority VARCHAR(20) DEFAULT 'Medium', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS units (id INT AUTO_INCREMENT PRIMARY KEY, subject_id INT NOT NULL, unit_name VARCHAR(100) NOT NULL, completion DECIMAL(5,2) DEFAULT 0, FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS topics (id INT AUTO_INCREMENT PRIMARY KEY, unit_id INT NOT NULL, topic_name VARCHAR(150) NOT NULL, status VARCHAR(20) DEFAULT 'Pending', FOREIGN KEY(unit_id) REFERENCES units(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(150) NOT NULL, description TEXT, due_date DATE, priority VARCHAR(20) DEFAULT 'Medium', status VARCHAR(20) DEFAULT 'Pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS study_sessions (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, subject_id INT NULL, duration INT NOT NULL DEFAULT 0, session_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, message TEXT NOT NULL, is_read TINYINT(1) DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reflections (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, notes TEXT, mood VARCHAR(50), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS simulations (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, expected_gpa DECIMAL(3,2), predicted_score DECIMAL(5,2), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS recommendations (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, recommendation TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
